464	function attachWebSocketServer(socketServer: WebSocketServer) {
465	    socketServer.on('connection', async (ws, req) => {
466	        if (shuttingDown) {
467	            ws.close(1012, 'Server shutting down');
468	            return;
469	        }
470	
471	        // Shell bridge via shell service proxy (avoids pm2 posix_spawn EBADF)
472	        if ((req as any).url === '/ws/shell') {
473	            ws.on('message', (raw: Buffer) => {
474	                try {
475	                    const { command } = JSON.parse(raw.toString());
476	                    if (typeof command !== 'string' || !command.trim()) return;
477	                    const http = require('http');
478	                    const body = JSON.stringify({ command });
479	                    const proxyReq = http.request({
480	                        hostname: '127.0.0.1', port: 3098, path: '/run', method: 'POST',
481	                        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body), 'X-API-KEY': process.env.SHELL_SERVICE_KEY || 'nudimmud-master-key-2026-04-23' },
482	                    }, (proxyRes: any) => {
483	                        let buf = '';
484	                        proxyRes.on('data', (chunk: Buffer) => {
485	                            buf += chunk.toString();
486	                            const parts = buf.split('\n\n');
487	                            buf = parts.pop() || '';
488	                            for (const part of parts) {
489	                                const raw2 = part.replace(/^data:\s*/, '').trim();
490	                                if (raw2) { try { ws.send(raw2); } catch {} }
491	                            }
492	                        });
493	                    });
494	                    proxyReq.on('error', (e: Error) => {
495	                        try { ws.send(JSON.stringify({ type: 'stderr', data: `shell service unavailable: ${e.message}` })); } catch {}
496	                    });
497	                    proxyReq.write(body);
498	                    proxyReq.end();
499	                    ws.on('close', () => proxyReq.destroy());
500	                } catch (_) {}
501	            });
502	            return;
503	        }
504	
505	        console.log('⬡ NEW_SEEKER_CONNECTED');
506	        logEvent(db, 'SYSTEM', 'WEBSOCKET', 'New seeker connected to the Command Center', 'INFO');
507	        ws.send(JSON.stringify(await buildStatusPayload()));
508	    });
509	
510	    EventBus.GlobalBus.on('CONCLAVE_EVENT', (artifact) => {
511	        if (shuttingDown) return;
512	
513	        socketServer.clients.forEach((client) => {
514	            if (client.readyState === 1) {
515	                client.send(JSON.stringify({
516	                    type: 'CONCLAVE_THOUGHT',
517	                    artifact
518	                }));
519	            }
520	        });
521	    });
522	}
