565	async function gracefulShutdown(signal: string) {
566	    if (shuttingDown) return;
567	    shuttingDown = true;
568	
569	    bootLog(`⬡ SHUTDOWN_SIGNAL_RECEIVED :: ${signal}`);
570	    clearTrackedTimers();
571	    guard.stop();
572	
573	    try {
574	        await vaultWatcherController?.close();
575	        bootLog('⬡ VAULT_WATCHER_STOPPED');
576	    } catch (error: any) {
577	        bootLog(`⬡ VAULT_WATCHER_STOP_ERROR: ${error.message}`);
578	    }
579	
580	    wss?.clients.forEach((client) => {
581	        if (client.readyState === 1) {
582	            client.close(1001, 'Server shutting down');
583	        }
584	    });
585	
586	    const forcedExit = setTimeout(() => {
587	        bootLog('⬡ FORCED_EXIT :: Timed out while shutting down');
588	        process.exit(1);
589	    }, 5000);
590	
591	    try {
592	        if (wss) {
593	            await new Promise<void>((resolve) => wss!.close(() => resolve()));
594	        }
595	        await new Promise<void>((resolve) => server.close(() => resolve()));
596	    } finally {
597	        clearTimeout(forcedExit);
598	    }
599	
600	    try {
601	        db.close();
602	        bootLog('⬡ DATABASE_CLOSED');
603	    } catch (error: any) {
604	        bootLog(`⬡ DATABASE_CLOSE_ERROR: ${error.message}`);
605	    }
606	
607	    process.exit(0);
608	}
