618	async function startServer() {
619	    for (let index = 0; index < PORT_CANDIDATES.length; index += 1) {
620	        const port = PORT_CANDIDATES[index];
621	        currentPort = port;
622	        const nextPort = PORT_CANDIDATES[index + 1];
623	
624	        const bindable = await canBindPort(port);
625	        if (!bindable) {
626	            if (nextPort) {
627	                bootLog(`⬡ PORT_COLLISION :: ${port} unavailable. Trying ${nextPort}...`);
628	                continue;
629	            }
630	            break;
631	        }
632	
633	        try {
634	            await listenOnPort(port);
