9	const runtimeEnv = ((import.meta as ImportMeta & { env?: RuntimeEnv }).env ?? {});
10	const SYSTEM_HOST = window.location.hostname || '127.0.0.1';
11	const HTTP_PROTOCOL = window.location.protocol === 'https:' ? 'https:' : 'http:';
12	const WS_PROTOCOL = HTTP_PROTOCOL === 'https:' ? 'wss:' : 'ws:';
13	const PRIMARY_PORT = runtimeEnv.VITE_API_PORT?.trim() || '3004';
14	const CONFIGURED_API_ORIGIN = runtimeEnv.VITE_API_ORIGIN?.trim();
15	const AUTH_HEADER_NAME = 'X-API-KEY';
16	const AUTH_STORAGE_KEY = 'nudimmud.runtime-api-key';
17	const BOOTSTRAP_PATH = runtimeEnv.VITE_API_BOOTSTRAP_PATH?.trim() || '/api/auth/bootstrap';
18	
19	let runtimeAuthToken: string | null | undefined;
20	let runtimeAuthTokenPromise: Promise<string | null> | null = null;
21	
22	function buildOrigin(protocol: string, port: string) {
23	    return `${protocol}//${SYSTEM_HOST}:${port}`;
24	}
25	
26	function normalizePath(pathOrUrl: string) {
27	    try {
28	        const parsed = new URL(pathOrUrl, buildOrigin(HTTP_PROTOCOL, PRIMARY_PORT));
29	        return `${parsed.pathname}${parsed.search}`;
30	    } catch {
31	        return pathOrUrl.startsWith('/') ? pathOrUrl : `/${pathOrUrl}`;
32	    }
33	}
34	
35	function dedupe(values: string[]) {
36	    return [...new Set(values.filter(Boolean))];
37	}
38	
39	function parsePortList(value?: string) {
40	    return (value || '')
41	        .split(',')
42	        .map((port) => port.trim())
43	        .filter(Boolean);
44	}
45	
46	const FALLBACK_PORTS = dedupe([
47	    ...parsePortList(runtimeEnv.VITE_API_FALLBACK_PORTS),
48	    runtimeEnv.VITE_API_FALLBACK_PORT?.trim() || '',
49	    '3005',
50	    '3003'
51	]);
52	
53	export const API_ORIGINS = dedupe([
54	    CONFIGURED_API_ORIGIN || buildOrigin(HTTP_PROTOCOL, PRIMARY_PORT),
55	    ...(CONFIGURED_API_ORIGIN ? [] : FALLBACK_PORTS.map((port) => buildOrigin(HTTP_PROTOCOL, port)))
56	]);
57	
58	export const WS_ORIGINS = API_ORIGINS.map((origin) =>
59	    origin.replace(/^https?:/, WS_PROTOCOL)
60	);
61	
62	export function apiUrl(pathOrUrl: string, origin = API_ORIGINS[0]) {
63	    return `${origin}${normalizePath(pathOrUrl)}`;
64	}
65	
66	function readStoredAuthToken() {
67	    try {
68	        return window.sessionStorage.getItem(AUTH_STORAGE_KEY)?.trim() || null;
69	    } catch {
70	        return null;
71	    }
72	}
73	
74	function storeAuthToken(token: string | null) {
75	    runtimeAuthToken = token;
76	    try {
77	        if (token) {
78	            window.sessionStorage.setItem(AUTH_STORAGE_KEY, token);
79	        } else {
80	            window.sessionStorage.removeItem(AUTH_STORAGE_KEY);
81	        }
82	    } catch {
83	        // Session storage is best-effort only.
84	    }
85	}
86	
87	function extractBootstrapToken(response: Response, payload: unknown) {
88	    const headerToken = response.headers.get(AUTH_HEADER_NAME) || response.headers.get(AUTH_HEADER_NAME.toLowerCase());
89	    if (headerToken?.trim()) return headerToken.trim();
90	
91	    if (typeof payload === 'string') {
92	        const trimmed = payload.trim();
93	        return trimmed || null;
94	    }
95	
96	    if (!payload || typeof payload !== 'object') return null;
97	
98	    const candidate = (payload as Record<string, unknown>).apiKey
99	        || (payload as Record<string, unknown>).api_key
100	        || (payload as Record<string, unknown>).token
101	        || (payload as Record<string, unknown>).authToken
102	        || (payload as Record<string, unknown>).value
103	        || (payload as Record<string, unknown>).key;
104	
105	    return typeof candidate === 'string' && candidate.trim() ? candidate.trim() : null;
106	}
107	
108	async function fetchFromOrigin(pathOrUrl: string, origin: string, init?: RequestInit) {
109	    return fetch(apiUrl(pathOrUrl, origin), init);
110	}
111	
112	async function fetchRuntimeBootstrapToken(origin: string) {
113	    try {
114	        const response = await fetchFromOrigin(BOOTSTRAP_PATH, origin, { credentials: 'same-origin' });
115	        if (!response.ok) return null;
116	
117	        const raw = await response.text().catch(() => '');
118	        try {
119	            return extractBootstrapToken(response, JSON.parse(raw));
120	        } catch {
121	            return extractBootstrapToken(response, raw);
122	        }
123	    } catch {
124	        return null;
125	    }
126	}
127	
128	async function resolveRuntimeAuthToken() {
129	    if (runtimeAuthToken !== undefined) {
130	        return runtimeAuthToken;
131	    }
132	
133	    const storedToken = readStoredAuthToken();
134	    if (storedToken) {
135	        runtimeAuthToken = storedToken;
136	        return storedToken;
137	    }
138	
139	    runtimeAuthTokenPromise ||= (async () => {
140	        for (const origin of API_ORIGINS) {
141	            const token = await fetchRuntimeBootstrapToken(origin);
142	            if (token) return token;
143	        }
144	        return null;
145	    })();
146	
147	    const token = await runtimeAuthTokenPromise;
148	    runtimeAuthTokenPromise = null;
149	    if (token) {
150	        storeAuthToken(token);
151	        return token;
152	    }
153	
154	    storeAuthToken(null);
155	    return null;
156	}
157	
158	function withAuthHeader(init: RequestInit | undefined, token: string | null) {
159	    const headers = new Headers(init?.headers || {});
160	    if (token && !headers.has(AUTH_HEADER_NAME)) {
161	        headers.set(AUTH_HEADER_NAME, token);
162	    }
163	    return {
164	        ...(init || {}),
165	        headers
166	    };
167	}
168	
169	export async function apiFetch(pathOrUrl: string, init?: RequestInit) {
170	    const attemptRequest = async (forceRefreshToken: boolean) => {
171	        if (forceRefreshToken) {
172	            storeAuthToken(null);
173	            runtimeAuthToken = undefined;
174	        }
175	
176	        const authToken = await resolveRuntimeAuthToken();
177	        const requestInit = withAuthHeader(init, authToken);
178	        let lastError: unknown;
179	
180	        for (const origin of API_ORIGINS) {
181	            try {
182	                return await fetchFromOrigin(pathOrUrl, origin, requestInit);
183	            } catch (error) {
184	                lastError = error;
185	            }
186	        }
187	
188	        throw lastError;
189	    };
190	
191	    const response = await attemptRequest(false);
192	    if (response.status !== 401) {
193	        return response;
194	    }
195	
196	    return attemptRequest(true);
197	}
198	
199	export async function apiFetchWithTimeout(pathOrUrl: string, timeoutMs: number, init: RequestInit = {}) {
200	    const controller = new AbortController();
201	    const upstreamSignal = init.signal;
202	    let timedOut = false;
203	
204	    const onUpstreamAbort = () => controller.abort();
205	    if (upstreamSignal) {
206	        if (upstreamSignal.aborted) {
207	            onUpstreamAbort();
208	        } else {
209	            upstreamSignal.addEventListener('abort', onUpstreamAbort, { once: true });
210	        }
211	    }
212	
213	    const timeoutId = globalThis.setTimeout(() => {
214	        timedOut = true;
215	        controller.abort();
216	    }, timeoutMs);
217	
218	    try {
219	        return await apiFetch(pathOrUrl, { ...init, signal: controller.signal });
220	    } catch (error: any) {
221	        if (timedOut && error?.name === 'AbortError') {
222	            const timeoutError = new Error(`REQUEST_TIMEOUT_${timeoutMs}MS`);
223	            timeoutError.name = 'AbortError';
224	            throw timeoutError;
225	        }
226	        throw error;
227	    } finally {
228	        globalThis.clearTimeout(timeoutId);
229	        if (upstreamSignal) {
230	            upstreamSignal.removeEventListener('abort', onUpstreamAbort);
231	        }
232	    }
233	}
