310	    handleNodeClick(clientX: number, clientY: number) {
311	        // Adjust for canvas offset and scale
312	        const x = (clientX - this.offset.x) / this.scale;
313	        const y = (clientY - this.offset.y) / this.scale;
314	
315	        // Find clicked node
316	        for (const node of this.nodes) {
317	            const dx = node.x - x;
318	            const dy = node.y - y;
319	            const dist = Math.sqrt(dx * dx + dy * dy);
320	            // generous hit area
